arguments.new_string:
char *err;
int rc;

/* All non-core subsystems must fail without std_core.
   Evaluate the registration call first (sets err), then check —
   C's argument evaluation order is unspecified, so don't pass both
   in the same call expression. */
err = NULL;
rc = frost_register_std_collections(rt, &err);
reg_expect_fail(rc, err, "std_core", "T2/collections-needs-core");

err = NULL;
rc = frost_register_std_async(rt, &err);
reg_expect_fail(rc, err, "std_core", "T2/async-needs-core");

err = NULL;
rc = frost_register_std_time(rt, &err);
reg_expect_fail(rc, err, "std_core", "T2/time-needs-core");

err = NULL;
rc = frost_register_std_io(rt, &err);
reg_expect_fail(rc, err, "std_core", "T2/io-needs-core");
